function valueKey(value){return value===null?"#NULL":typeof value+":"+String(value);}function rowKey(row){return row.map(valueKey).join("\u001f");}function bagCounts(rows){var m=new Map();rows.forEach(function(row){var k=rowKey(row);m.set(k,(m.get(k)||0)+1);});return m;}function bagEqual(a,b){var x=bagCounts(a),y=bagCounts(b);if(x.size!==y.size)return false;for(var pair of x)if(y.get(pair[0])!==pair[1])return false;return true;}function distinctRows(rows){var seen=new Set();return rows.filter(function(row){var k=rowKey(row);if(seen.has(k))return false;seen.add(k);return true;});}
