function choice(id,label,answer,options){return{id:id,label:label,kind:"choice",answer:String(answer),options:options.map(function(x){return{value:String(x[0]),label:String(x[1])};})};}function typed(id,label,answer,kind){return{id:id,label:label,kind:kind,answer:String(answer)};}function yn(value){return choice("answer",t("fieldLabels.answer","Answer"),value?"yes":"no",[["yes",t("generated.choices.yes","Yes")],["no",t("generated.choices.no","No")]]);}function tfu(value){return choice("answer",t("fieldLabels.answer","Answer"),value,[["T",t("generated.choices.true","TRUE")],["F",t("generated.choices.false","FALSE")],["U",t("generated.choices.unknown","UNKNOWN")]]);}function validChoice(value){return choice("answer",t("fieldLabels.answer","Answer"),value?"valid":"invalid",[["valid",t("generated.choices.valid","Valid")],["invalid",t("generated.choices.invalid","Error")]]);}function allowedChoice(value){return choice("answer",t("fieldLabels.answer","Answer"),value?"allowed":"rejected",[["allowed",t("generated.choices.allowed","Allowed")],["rejected",t("generated.choices.rejected","Rejected")]]);}
