function loadProgress(){return mergeProgress(PracticeLabUI.readJson(STORAGE_KEY));}function saveProgress(){PracticeLabUI.writeJson(STORAGE_KEY,progress);}function getStat(id,level){var key=statKey(id,level);if(!progress.stats[key])progress.stats[key]=blankStat();return progress.stats[key];}function updateMastery(s){var accuracy=s.attempts?s.correct/s.attempts:0,recent=s.recent.length?s.recent.filter(Boolean).length/s.recent.length:0;s.mastery=Math.round(100*Math.min(1,.55*accuracy+.35*recent+.1*Math.min(1,s.attempts/8)));}function aggregateProgress(){var out={attempts:0,correct:0,totalMs:0,masteryTotal:0,practiced:0};Object.keys(progress.stats).forEach(function(key){var s=progress.stats[key];out.attempts+=s.attempts;out.correct+=s.correct;out.totalMs+=s.totalMs;if(s.attempts){out.masteryTotal+=s.mastery;out.practiced+=1;}});return out;}
